package com.ugro.skaleup.rag;
import org.apache.pdfbox.Loader; import org.apache.pdfbox.pdmodel.PDDocument; import org.apache.pdfbox.text.PDFTextStripper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.io.*; import java.nio.file.*; import java.util.*; import java.util.regex.*; import java.util.stream.Stream;
@Service public class PdfIngestionService {
 private final Path dir; public PdfIngestionService(@Value("${RAG_DATA_DIR:./data}")String d){dir=Path.of(d);}
 public List<VectorStore.ChunkText> ingest() throws Exception{if(!Files.isDirectory(dir))throw new FileNotFoundException("Data directory not found: "+dir);List<VectorStore.ChunkText>out=new ArrayList<>();try(Stream<Path> s=Files.list(dir)){for(Path p:s.filter(x->x.toString().toLowerCase().endsWith(".pdf")).sorted().toList()){try(PDDocument doc=Loader.loadPDF(p.toFile())){PDFTextStripper stripper=new PDFTextStripper();String prev="";for(int i=1;i<=doc.getNumberOfPages();i++){stripper.setStartPage(i);stripper.setEndPage(i);String text=clean(stripper.getText(doc));if(text.isBlank())continue;String combined=prev.length()>250?prev.substring(Math.max(0,prev.length()-250))+"\n"+text:text;for(String c:chunk(combined,1200,180))out.add(new VectorStore.ChunkText(p.getFileName().toString(),i,c));prev=text;}}catch(Exception e){System.err.println("Skipping "+p+": "+e.getMessage());}}}return out;}
 private String clean(String s){return s.replace('\u00a0',' ').replaceAll("[ \\t]+"," ").replaceAll("\\n{3,}","\\n\\n").trim();}
 private List<String>chunk(String s,int size,int overlap){List<String>o=new ArrayList<>();int start=0;while(start<s.length()){int end=Math.min(s.length(),start+size);if(end<s.length()){int p=Math.max(s.lastIndexOf('.',end),Math.max(s.lastIndexOf('।',end),s.lastIndexOf('?',end)));if(p>start+size/2)end=p+1;}String x=s.substring(start,end).trim();if(x.length()>40)o.add(x);if(end>=s.length())break;start=Math.max(start+1,end-overlap);}return o;}
}
